using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "MartyrPuppetOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/MartyrPuppet Omen Data")]
public class MartyrPuppetOmenData : OmenData
{
	private Func<int, int> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate(int corruptAmount)
		{
			if (corruptAmount < ActionValue)
			{
				return corruptAmount;
			}
			omenInstance.EnqueueOmenFeedbackAndPlay();
			return Mathf.Max(corruptAmount - 1, 0);
		};
		ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerCorruptedFinalModifierOmenAction = omenAction;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerCorruptedFinalModifierOmenAction = null;
	}
}
